pub fn contains(hay: &[u8], needle: &[u8]) -> bool {
    if needle.len() > hay.len() { return false; }
    let last = hay.len() - needle.len();
    let mut i = 0;
    loop {
        if starts_at(hay, needle, i) { return true; }
        if i == last { return false; }
        i += 1;
    }
}

