display_classifiers.starts_at.code:
pub fn starts_at(hay: &[u8], needle: &[u8], at: usize) -> bool {
    if at > hay.len() { return false; }
    if needle.len() > hay.len() - at { return false; }
    &hay[at..at + needle.len()] == needle
}

